function Greeting({ name = 'Guest', greeting = 'Hello' }) {
  return <h1>{greeting}, {name}!</h1>;
}

// Uses defaults
<Greeting /> // Hello, Guest!

// Overrides defaults
<Greeting name="Alice" /> // Hello, Alice!
<Greeting name="Bob" greeting="Hi" /> // Hi, Bob!

function Card({ children, title }) {
  return (
    <div className="card">
      <h2>{title}</h2>
      <div className="card-content">
        {children}
      </div>
    </div>
  );
}

// Usage
<Card title="Welcome">
  <p>This is the card content</p>
  <button>Click me</button>
</Card>

function UserInfo({ name, email, age, role }) {
  return (
    <div>
      <p>Name: {name}</p>
      <p>Email: {email}</p>
      <p>Age: {age}</p>
      <p>Role: {role}</p>
    </div>
  );
}

// Without spread
<UserInfo name="Alice" email="alice@example.com" age={25} role="admin" />

// With spread
const user = { name: 'Alice', email: 'alice@example.com', age: 25, role: 'admin' };
<UserInfo {...user} />

function MouseTracker({ render }) {
  const [position, setPosition] = useState({ x: 0, y: 0 });

  const handleMouseMove = (e) => {
    setPosition({ x: e.clientX, y: e.clientY });
  };

  return (
    <div onMouseMove={handleMouseMove}>
      {render(position)}
    </div>
  );
}

// Usage
<MouseTracker
  render={({ x, y }) => (
    <p>Mouse is at ({x}, {y})</p>
  )}
/>
